      "content": "/**\n * Observe-only DeepSeek Harness evidence receipt plugin.\n *\n * @module qiushi-dsh-evidence-audit\n */\n\nimport { chmodSync, mkdirSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { dirname, isAbsolute, join, resolve } from 'node:path'\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport {\n  EvidenceReceiptWriter,\n  hashObservedValue,\n} from './receipt.ts'\nimport type { ReceiptInput, Sha256 } from './receipt.ts'\n\n/** Cordis plugin name used by Loader diagnostics. */\nexport const name = 'qiushi-evidence-audit'\n\n/** Receipt output configuration. */\nexport interface Config {\n  /** Absolute JSONL destination. Omit for `$DSH_HOME/evidence-audit/evidence-receipts.jsonl`. */\n  outputPath?: string\n}\n\n/** Loader validation for {@link Config}. */\nexport const Config: z<Config> = (z.object({\n  outputPath: z.string(),\n}) as z<Config>).default({})\n\ninterface SessionLike {\n  readonly id: string\n}\n\ninterface SessionEventLike {\n  readonly type: string\n  readonly seq: number\n  readonly time: number\n  readonly data: unknown\n  readonly ignorable?: true\n}\n\ninterface ToolExecutionLike {\n  readonly name: string\n  readonly callId: string\n  readonly rootCallId: string\n  readonly arguments: unknown\n  readonly parent?: symbol\n  readonly agent?: { readonly session: SessionLike }\n}\n\ninterface ToolResultLike {\n  readonly isError: boolean\n  readonly content: readonly unknown[]\n  readonly value?: unknown\n  readonly error?: { readonly info?: { readonly code?: string } }\n  readonly meta?: unknown\n  readonly additionalContexts?: readonly unknown[]\n  readonly concludesTurn?: true\n}\n\ninterface EvidenceContext {\n  readonly logger: { warn(message: string): void }\n  on(name: 'session/event', listener: (session: SessionLike, event: SessionEventLike) => void): () => void\n  on(name: 'tools/result', listener: (exec: ToolExecutionLike, result: ToolResultLike) => void): () => void\n  effect(execute: () => () => Promise<void>, label?: string): unknown\n}\n\n/** Resolve the configured path without ever defaulting to the working directory. */\nexport function resolveOutputPath(\n  configuredPath: string | undefined,\n  dshHome: string | undefined = process.env.DSH_HOME,\n  _cwd: string = process.cwd(),\n): string {\n  if (configuredPath !== undefined) {\n    if (!isAbsolute(configuredPath)) {\n      throw new TypeError(`qiushi-evidence-audit: outputPath must be absolute, got ${JSON.stringify(configuredPath)}`)\n    }\n    return resolve(configuredPath)\n  }\n  const selectedHome = dshHome === undefined || dshHome.trim().length === 0\n    ? join(homedir(), '.dsh')\n    : expandHomePath(dshHome)\n  const home = resolve(selectedHome)\n  return join(home, 'evidence-audit', 'evidence-receipts.jsonl')\n}\n\nfunction expandHomePath(path: string): string {\n  if (path === '~') return homedir()\n  if (path.startsWith('~/') || path.startsWith('~\\\\')) return join(homedir(), path.slice(2))\n  return path\n}\n\nfunction sessionReceipt(session: SessionLike, event: SessionEventLike): ReceiptInput {\n  return {\n    kind: 'session-event',\n    sessionIdHash: hashObservedValue(session.id),\n    eventType: event.type,\n    eventSeq: event.seq,\n    eventTime: event.time,\n    eventDataHash: hashObservedValue(event.data),\n    ...event.ignorable === true ? { ignorable: true } : {},\n  }\n}\n\nfunction toolReceipt(exec: ToolExecutionLike, result: ToolResultLike): ReceiptInput {\n  const sessionIdHash: Sha256 | null = exec.agent === undefined\n    ? null\n    : hashObservedValue(exec.agent.session.id)\n  const outcome = {\n    isError: result.isError,\n    content: result.content,\n    ...result.value === undefined ? {} : { value: result.value },\n    ...result.error === undefined ? {} : { error: result.error },\n    ...result.meta === undefined ? {} : { meta: result.meta },\n    ...result.additionalContexts === undefined ? {} : { additionalContexts: result.additionalContexts },\n    ...result.concludesTurn === undefined ? {} : { concludesTurn: result.concludesTurn },\n  }\n  const errorCode = result.error?.info?.code\n  return {\n    kind: 'tool-result',\n    sessionIdHash,\n    toolName: exec.name,\n    callIdHash: hashObservedValue(exec.callId),\n    rootCallIdHash: hashObservedValue(exec.rootCallId),\n    argumentsHash: hashObservedValue(exec.arguments),\n    outcomeHash: hashObservedValue(outcome),\n    isError: result.isError,\n    hasParent: exec.parent !== undefined,\n    ...errorCode === undefined ? {} : { errorCode },\n  }\n}\n\nfunction appendContained(\n  ctx: EvidenceContext,\n  writer: EvidenceReceiptWriter,\n  source: 'session/event' | 'tools/result',\n  create: () => ReceiptInput,\n): void {\n  try {\n    writer.append(create())\n  } catch (error: unknown) {\n    const message = error instanceof Error ? error.message : String(error)\n    ctx.logger.warn(`qiushi-evidence-audit: ${source} receipt failed: ${message}`)\n  }\n}\n\n/**\n * Open the hash chain and register contained observers for both official feeds.\n *\n * @param context - Cordis plugin context.\n * @param config - absolute output override, or the safe Harness-home default.\n */\nexport async function apply(context: Context, config: Config = {}): Promise<void> {\n  const ctx = context as unknown as EvidenceContext\n  const path = resolveOutputPath(config.outputPath)\n  if (config.outputPath === undefined) {\n    mkdirSync(dirname(path), { recursive: true, mode: 0o700 })\n    chmodSync(dirname(path), 0o700)\n  }\n  const writer = await EvidenceReceiptWriter.open(path)\n  let disposeSessionEvent: (() => void) | undefined\n  let disposeToolResult: (() => void) | undefined\n  try {\n    disposeSessionEvent = ctx.on('session/event', (session, event) => {\n      appendContained(ctx, writer, 'session/event', () => sessionReceipt(session, event))\n    })\n    disposeToolResult = ctx.on('tools/result', (exec, result) => {\n      appendContained(ctx, writer, 'tools/result', () => toolReceipt(exec, result))\n    })\n    ctx.effect(() => async () => {\n      disposeToolResult?.()\n      disposeSessionEvent?.()\n      await writer.close()\n    }, 'qiushi evidence receipt observers and writer')\n  } catch (error: unknown) {\n    disposeToolResult?.()\n    disposeSessionEvent?.()\n    await writer.close()\n    throw error\n  }\n}\n\nexport {\n  EvidenceReceiptWriter,\n  canonicalJson,\n  hashObservedValue,\n  verifyReceiptFile,\n} from './receipt.ts'\nexport type {\n  EvidenceReceipt,\n  ReceiptInput,\n  ReceiptVerification,\n  SessionEventReceiptInput,\n  Sha256,\n  ToolResultReceiptInput,\n} from './receipt.ts'\n"
